'use strict';
(()=>{
 const origin=document.querySelector('meta[name=justin-api-origin]')?.content||location.origin,banner=document.createElement('aside');banner.id='live-notices';banner.setAttribute('aria-label','Game announcements');document.querySelector('.ranked-note')?.after(banner)||document.querySelector('.instruction').after(banner);
 let muteUntil=0,dismissed=new Set(),generation=0,account='',lastKey='',notices=[],stream=null,streamReady=false,latestLive=0,lastSoundMuted=null;
 const muted=()=>Date.now()<muteUntil;
 function render(){const visible=notices.filter(n=>n.endsAt>Date.now()&&!dismissed.has(n.id)),key=JSON.stringify(visible);if(key!==lastKey){lastKey=key;banner.replaceChildren(...visible.map(n=>{const card=document.createElement('div'),text=document.createElement('p'),author=document.createElement('small'),close=document.createElement('button');text.textContent=n.message;author.textContent='announcement from '+n.author;close.type='button';close.textContent='×';close.setAttribute('aria-label','Dismiss announcement');close.onclick=()=>{dismissed.add(n.id);render()};card.append(author,text,close);return card}))}const sound=document.getElementById('audio');const silenced=muted();if(sound&&sound.muted!==silenced)sound.muted=silenced;document.body.classList.toggle('account-silenced',silenced);if(lastSoundMuted!==silenced){lastSoundMuted=silenced;window.dispatchEvent(new CustomEvent('justin-sound-policy',{detail:{muted:silenced,until:muteUntil}}))}}
 function apply(data){if(!data||Number(data.serverNow||0)<latestLive)return;latestLive=Number(data.serverNow||0);const offset=(data.serverNow||Date.now())-Date.now();muteUntil=Number(data.muteUntil||0)-offset;notices=(data.announcements||[]).map(n=>({...n,endsAt:n.endsAt-offset}));render()}
 async function poll(){const ticket=generation;try{const r=await fetch(new URL('/api/live',origin),{credentials:'include',signal:AbortSignal.timeout(8000)});if(r.ok){const data=await r.json();if(ticket===generation)apply(data)}}catch{}}
 function connect(){stream?.close();stream=null;streamReady=false;if(document.hidden)return;if(window.EventSource){const ticket=generation;stream=new EventSource(new URL('/api/live-stream',origin),{withCredentials:true});stream.onopen=()=>{streamReady=true};stream.onmessage=e=>{if(ticket!==generation)return;try{apply(JSON.parse(e.data))}catch{}};stream.onerror=()=>{streamReady=false}}poll()}
 window.JustinLive={apply,muted};window.addEventListener('justin-account-change',e=>{const next=e.detail.user?.id||'';if(next!==account){account=next;generation++;latestLive=0;notices=[];muteUntil=0;lastKey='';render();connect()}});document.getElementById('audio')?.addEventListener('play',render);setInterval(()=>{if(!document.hidden)render()},250);setInterval(()=>{if(!document.hidden&&!streamReady)poll()},2000);document.addEventListener('visibilitychange',connect);window.addEventListener('pagehide',()=>stream?.close());connect();
})();
